// ---------- construcao da folha ----------
function buildXlsx(meta) {
  const moedaFmt = meta.moeda === 'USD' ? '$' : 'R$';
  const fmtBR = v => moedaFmt + ' ' + (Number(v) || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const gastos = meta.gastos || [];
  const total = gastos.reduce((s, g) => s + (Number(g.valor) || 0), 0);

  // agregado por categoria
  const porCat = {};
  for (const g of gastos) porCat[g.categoria] = (porCat[g.categoria] || 0) + (Number(g.valor) || 0);
  const cats = Object.entries(porCat).sort((a, b) => b[1] - a[1]);
  const maior = gastos.reduce((m, g) => (Number(g.valor) || 0) > (Number(m.valor) || 0) ? g : m, gastos[0] || {});

  const rows = []; // {cells:[{col, style, v|t}], ht}
  const merges = [];
  let R = 0;
  function addRow(cells, ht) { R++; rows.push({ r: R, cells, ht }); return R; }
  function txt(col, s, style) { return { col, t: s, s: style }; }
  function num(col, v, style) { return { col, v, s: style }; }
  function merge(r, c1, c2) { merges.push(`${colLetter(c1)}${r}:${colLetter(c2)}${r}`); }

  // titulo
  let r = addRow([txt(1, 'RELATORIO DE GASTOS', 1), txt(2,'',1), txt(3,'',1), txt(4,'',1), txt(5,'',1), txt(6,'',1)], 30);
  merge(r, 1, 6);
  r = addRow([txt(1, `${meta.nome || ''} - ${meta.label_periodo || ''} - gerado em ${meta.data_geracao || ''}`, 2), txt(2,'',2), txt(3,'',2), txt(4,'',2), txt(5,'',2), txt(6,'',2)], 16);
  merge(r, 1, 6);
  addRow([]);

  // resumo
  r = addRow([txt(1, 'RESUMO', 3), txt(2,'',3), txt(3,'',3), txt(4,'',3), txt(5,'',3), txt(6,'',3)], 18);
  merge(r, 1, 6);
  addRow([txt(1, 'Total do periodo', 4), num(2, Math.round(total * 100) / 100, 18)]);
  addRow([txt(1, 'Lancamentos', 4), num(2, gastos.length, 4)]);
  r = addRow([txt(1, 'Maior gasto', 4), txt(2, `${maior.descricao || '-'} (${fmtBR(maior.valor)})`, 0)]);
  merge(r, 2, 6);
  addRow([]);

  // por categoria
  r = addRow([txt(1, 'POR CATEGORIA', 3), txt(2,'',3), txt(3,'',3), txt(4,'',3), txt(5,'',3), txt(6,'',3)], 18);
  merge(r, 1, 6);
  addRow([txt(1, 'Categoria', 7), txt(2, 'Valor', 7), txt(3, '% do total', 7)]);
  cats.forEach(([c, v], i) => {
    const z = i % 2 === 1;
    addRow([txt(1, c, z ? 9 : 8), num(2, Math.round(v * 100) / 100, z ? 11 : 10), num(3, total ? v / total : 0, z ? 13 : 12)]);
  });
  addRow([txt(1, 'TOTAL', 14), num(2, Math.round(total * 100) / 100, 15), txt(3, '', 14)]);
  addRow([]);

  // detalhes
  r = addRow([txt(1, 'LANCAMENTOS DETALHADOS', 3), txt(2,'',3), txt(3,'',3), txt(4,'',3), txt(5,'',3), txt(6,'',3)], 18);
  merge(r, 1, 6);
  addRow([txt(1, 'Data', 7), txt(2, 'Descricao', 7), txt(3, 'Categoria', 7), txt(4, 'Forma de pagamento', 7), txt(5, 'Valor', 7), txt(6, 'Observacoes', 7)]);
  gastos.forEach((g, i) => {
    const z = i % 2 === 1;
    addRow([
      txt(1, g.data || '', z ? 17 : 16),
      txt(2, g.descricao || '', z ? 9 : 8),
      txt(3, g.categoria || '', z ? 9 : 8),
      txt(4, g.forma || '', z ? 9 : 8),
      num(5, Math.round((Number(g.valor) || 0) * 100) / 100, z ? 11 : 10),
      txt(6, g.obs || '', z ? 9 : 8)
    ]);
  });
  addRow([txt(1, '', 14), txt(2, 'TOTAL', 14), txt(3, '', 14), txt(4, '', 14), num(5, Math.round(total * 100) / 100, 15), txt(6, '', 14)]);

  // XML da folha
  const rowsXml = rows.map(row => {
    const cellsXml = (row.cells || []).map(c => {
      const ref = colLetter(c.col) + row.r;
      if (c.v != null) return `<c r="${ref}" s="${c.s}"><v>${c.v}</v></c>`;
      return `<c r="${ref}" s="${c.s}" t="inlineStr"><is><t xml:space="preserve">${esc(c.t)}</t></is></c>`;
    }).join('');
    const htAttr = row.ht ? ` ht="${row.ht}" customHeight="1"` : '';
    return `<row r="${row.r}"${htAttr}>${cellsXml}</row>`;
  }).join('');

  const sheetXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<cols>
<col min="1" max="1" width="13" customWidth="1"/>
<col min="2" max="2" width="44" customWidth="1"/>
<col min="3" max="3" width="16" customWidth="1"/>
<col min="4" max="4" width="20" customWidth="1"/>
<col min="5" max="5" width="15" customWidth="1"/>
<col min="6" max="6" width="50" customWidth="1"/>
</cols>
<sheetData>${rowsXml}</sheetData>
<mergeCells count="${merges.length}">${merges.map(m => `<mergeCell ref="${m}"/>`).join('')}</mergeCells>
</worksheet>`;

  const contentTypes = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
<Default Extension="xml" ContentType="application/xml"/>
<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>
</Types>`;
  const rels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
</Relationships>`;
  const wbRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>`;
  const workbook = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<sheets><sheet name="Gastos" sheetId="1" r:id="rId1"/></sheets>
</workbook>`;

  const zip = zipStore([
    { name: '[Content_Types].xml', data: Buffer.from(contentTypes, 'utf8') },
    { name: '_rels/.rels', data: Buffer.from(rels, 'utf8') },
    { name: 'xl/workbook.xml', data: Buffer.from(workbook, 'utf8') },
    { name: 'xl/_rels/workbook.xml.rels', data: Buffer.from(wbRels, 'utf8') },
    { name: 'xl/styles.xml', data: Buffer.from(stylesXml(moedaFmt), 'utf8') },
    { name: 'xl/worksheets/sheet1.xml', data: Buffer.from(sheetXml, 'utf8') }
  ]);
  return zip.toString('base64');
}

const meta = $('Montar Meta').first().json;
return [{ json: { xlsx_b64: buildXlsx(meta) } }];
